#!/usr/bin/env python3
"""Structural invariants over random replays, checked on the JSON boundary."""
import json
import math
import random
import subprocess
import sys
from fractions import Fraction
from math import gcd

sys.path.insert(0, '/workspace/tmp')
import diff_test  # noqa: E402

MAIN = '/workspace/submission/main.py'
problems = []


def walk_numbers(node, path=""):
    if isinstance(node, bool):
        return  # booleans are only legal in the documented spots, checked below
    if isinstance(node, float):
        problems.append("float in output at " + path)
    if isinstance(node, list):
        for i, child in enumerate(node):
            walk_numbers(child, path + "[%d]" % i)


def check_case(index, request, answer):
    for stream_request, stream_answer in zip(request["streams"],
                                             answer["streams"]):
        topo = stream_request["topology"]
        settings = stream_request["settings"]
        links = {(n["id"], n["name"]) for n in topo["nodes"]}
        names = {n["id"]: n["name"] for n in topo["nodes"]}
        external = set(topo["external_nodes"])
        flows = []
        for link in topo["links"]:
            for a, b in ((link["source"], link["target"]),
                         (link["target"], link["source"])):
                flows.append((a, b))
                flows.append((a, b))
        flows = sorted(set(flows))
        pairs = []
        for link in topo["links"]:
            pairs.append((link["source"], link["target"]))
            pairs.append((link["target"], link["source"]))
        for nid in sorted(names):
            if names[nid] in external:
                pairs.append((-1, nid))
                pairs.append((nid, -1))
        pairs.sort()
        keys = set()
        for a, b in pairs:
            if a == -1:
                keys.add("low_%s_origination" % names[b])
            elif b == -1:
                keys.add("low_%s_termination" % names[a])
            else:
                keys.add("low_%s_egress_to_%s" % (names[a], names[b]))
                keys.add("low_%s_ingress_from_%s" % (names[b], names[a]))
        events = stream_answer["events"]
        if len(events) != len(stream_request["events"]):
            problems.append("event count mismatch")
        for source, answer_event in zip(stream_request["events"], events):
            op = answer_event["op"]
            if op != source["op"]:
                problems.append("op order mismatch")
            if op == "patch":
                if set(answer_event) != {"op", "accepted"} or type(
                        answer_event["accepted"]) is not bool:
                    problems.append("patch shape")
            elif op == "routes":
                if set(answer_event) != {"op", "accepted"} or \
                        answer_event["accepted"] is not True:
                    problems.append("routes shape")
            elif op == "repair":
                if set(answer_event) != {"op", "id", "cache_hit", "links",
                                         "order", "counters"}:
                    problems.append("repair field set")
                if answer_event["id"] != source["id"]:
                    problems.append("repair id")
                if type(answer_event["cache_hit"]) is not bool:
                    problems.append("cache_hit type")
                rows = answer_event["links"]
                if [(r[0], r[1]) for r in rows] != pairs:
                    problems.append("links not canonical/complete")
                for row in rows:
                    num, den = row[3], row[4]
                    if den <= 0 or gcd(num, den) != 1 or num < 0:
                        problems.append("confidence not reduced positive")
                    if num * 1.0 / den > 5 + 1e-12:
                        problems.append("confidence above 5")
                    if not all(type(v) is int for v in row):
                        problems.append("non-integer link field")
                order = answer_event["order"]
                if sorted((p[0], p[1]) for p in order) != pairs or len(order) != len(pairs):
                    problems.append("order is not a permutation of flows")
                counters = answer_event["counters"]
                if set(counters) != keys:
                    problems.append("counter key universe mismatch")
                for cell in counters.values():
                    if set(cell) != {"corrected", "confidence"}:
                        problems.append("counter cell shape")
                    if type(cell["corrected"]) is not int:
                        problems.append("corrected not int")
                    conf = cell["confidence"]
                    if len(conf) != 2 or not all(type(v) is int for v in conf) or conf[1] <= 0:
                        problems.append("confidence pair")
            else:
                if set(answer_event) != {"op", "id", "checked", "passed",
                                         "consistent", "failed"}:
                    problems.append("validate field set")
                checked, passed = answer_event["checked"], answer_event["passed"]
                if not (type(checked) is int and type(passed) is int):
                    problems.append("counters not ints")
                if not 0 <= passed <= checked:
                    problems.append("passed outside [0, checked]")
                if checked == 0:
                    if answer_event["consistent"] is not None:
                        problems.append("consistency should be null")
                else:
                    gamma = Fraction(settings["gamma"][0], settings["gamma"][1])
                    want = Fraction(passed, checked) >= gamma
                    if answer_event["consistent"] is not want:
                        problems.append("consistency value")
                if answer_event["failed"] != sorted(answer_event["failed"]):
                    problems.append("failed not ASCII sorted")
                if len(answer_event["failed"]) > checked:
                    problems.append("more failures than checks")
    walk_numbers(json.loads(json.dumps(answer)))


for case in range(120):
    rng = random.Random(31337 + case)
    streams = [diff_test.make_stream(rng, nodes=rng.randint(2, 7),
                                     ext=rng.randint(1, 4),
                                     events=rng.randint(1, 10))
               for _ in range(rng.randint(1, 3))]
    request = {"streams": streams}
    blob = json.dumps(request, separators=(",", ":")).encode()
    proc = subprocess.run([sys.executable, '-B', '-u', MAIN], input=blob,
                          capture_output=True, cwd='/workspace/tmp/scratch',
                          env={'PATH': '/usr/local/bin:/usr/bin:/bin',
                               'PYTHONPATH': '/workspace/submission'})
    if proc.returncode:
        problems.append("nonzero exit: " + proc.stderr.decode()[:400])
        continue
    answer = json.loads(proc.stdout.decode())
    check_case(case, request, answer)
    if problems:
        print("case", case)
        break

print("invariant problems:", len(problems))
for problem in problems[:10]:
    print(" -", problem)
sys.exit(1 if problems else 0)
